// The guardrail's measured accuracy, as shown in the header and next to results.
// These numbers are generated by evals/build_dashboard.py from the eval reports,
// and CI fails if they drift (the badge once said "100%" from a stale July file
// while the eval it claimed to summarise said 97.9%).
import results from '../eval-results.json'

const hasMetrics = results && typeof results.accuracy === 'number'

function pct(x) {
  return typeof x === 'number' ? `${Math.round(x * 100)}%` : 'n/a'
}

function detail() {
  return `${results.n} labelled statements: ${results.missed_fabrications} fabrications missed, ` +
    `${results.false_flags} true ${results.false_flags === 1 ? 'claim' : 'claims'} wrongly flagged`
}

// Compact header badge: always-visible, honest credibility signal.
export function TrustBadge({ onOpen }) {
  if (!hasMetrics) return null
  return (
    <button type="button" className="trustbadge" title={`${detail()}. Click for how it is measured.`} onClick={onOpen}>
      <span className="trustbadge__dot" aria-hidden="true" />
      Guardrail {pct(results.accuracy)} accurate
    </button>
  )
}

// Fuller panel with stat tiles, shown beside the guardrail results.
export default function TrustPanel({ onOpen }) {
  if (!hasMetrics) return null
  return (
    <div className="card trust">
      <div className="trust__head">
        <h3 className="card__title">🛡️ Measured guardrail accuracy</h3>
        <span className="trust__n">n = {results.n} labelled statements</span>
      </div>
      <div className="trust__tiles">
        <div className="tile">
          <span className="tile__num">{pct(results.accuracy)}</span>
          <span className="tile__label">Accuracy</span>
        </div>
        <div className="tile">
          <span className="tile__num">{results.missed_fabrications}</span>
          <span className="tile__label">Fabrications missed</span>
        </div>
        <div className="tile">
          <span className="tile__num">{results.false_flags}</span>
          <span className="tile__label">True claims wrongly flagged</span>
        </div>
      </div>
      <p className="trust__note">
        It is built to miss nothing and to occasionally over-flag, because a wrongly
        flagged bullet costs you a click and a missed fabrication costs you the interview.{' '}
        {onOpen && (
          <button type="button" className="linkbtn" onClick={onOpen}>See how every number is measured</button>
        )}
      </p>
    </div>
  )
}
